\documentclass[tikz, border=20pt]{standalone}
\usepackage{CJKutf8}
\usetikzlibrary{shapes, arrows.meta, positioning, calc}

\begin{document}
\begin{CJK*}{UTF8}{gbsn}

\begin{tikzpicture}[
    font=\sffamily,
    % 定义电子的样式
    electron/.style={circle, fill=black, inner sep=0pt, minimum size=5pt},
    c-elec/.style={electron, fill=black!80},  % 碳的价电子：深灰/黑
    h-elec/.style={electron, fill=blue!60},   % 氢的价电子：蓝色
    o-elec/.style={electron, fill=red!70},    % 氧的价电子：红色
    atom/.style={font=\Large\bfseries, align=center}
]

% ==========================================
% 第 1 步: 甲烷 (CH4)
% ==========================================
\begin{scope}[yshift=0cm]
    \node[atom] at (0,0) {C};
    \node[atom, text=blue!90] at (0, 1.6) {H};
    \node[atom, text=blue!90] at (0,-1.6) {H};
    \node[atom, text=blue!90] at (-1.6,0) {H};
    \node[atom, text=blue!90] at ( 1.6,0) {H};

    \node[c-elec] at (-0.12, 0.8) {}; \node[h-elec] at (0.12, 0.8) {}; 
    \node[c-elec] at (-0.12,-0.8) {}; \node[h-elec] at (0.12,-0.8) {}; 
    \node[c-elec] at (-0.8, 0.12) {}; \node[h-elec] at (-0.8,-0.12) {};
    \node[c-elec] at ( 0.8, 0.12) {}; \node[h-elec] at ( 0.8,-0.12) {};

    \draw[dashed, very thick, black!80, rounded corners=14pt] (-1.1, -1.1) rectangle (1.1, 1.1);

    % 向下箭头 1
    \draw[-{Stealth[scale=1.2]}, line width=1.5pt, draw=black!60] 
        (0, -2.0) -- (0, -4.0) node[midway, right=10pt, font=\small\bfseries, text=black] {加氧 ($-2e^-$)};
\end{scope}

% ==========================================
% 第 2 步: 甲醇 (CH3OH)
% ==========================================
\begin{scope}[yshift=-6.2cm]
    \node[atom] at (0,0) {C};
    \node[atom, text=blue!90] at (0, 1.6) {H};
    \node[atom, text=blue!90] at (0,-1.6) {H};
    \node[atom, text=blue!90] at (-1.6,0) {H};
    \node[atom, text=red!80]  at ( 1.6,0) {O};
    \node[atom, text=blue!90] at ( 3.2,0) {H};

    \node[c-elec] at (-0.12, 0.8) {}; \node[h-elec] at (0.12, 0.8) {};
    \node[c-elec] at (-0.12,-0.8) {}; \node[h-elec] at (0.12,-0.8) {};
    \node[c-elec] at (-0.8, 0.12) {}; \node[h-elec] at (-0.8,-0.12) {};

    \node[c-elec] at ( 0.8, 0.12) {}; \node[o-elec] at ( 0.8,-0.12) {};
    \node[o-elec] at ( 2.4, 0.12) {}; \node[h-elec] at ( 2.4,-0.12) {};
    \node[o-elec] at ( 1.48, 0.8) {}; \node[o-elec] at ( 1.72, 0.8) {};
    \node[o-elec] at ( 1.48,-0.8) {}; \node[o-elec] at ( 1.72,-0.8) {};

    \draw[dashed, very thick, black!80, rounded corners=12pt] (-1.1, -1.1) rectangle (0.4, 1.1);
    \draw[dashed, very thick, red!80, rounded corners=14pt] (0.5, -1.1) rectangle (2.7, 1.1);

    % 向下箭头 2
    \draw[-{Stealth[scale=1.2]}, line width=1.5pt, draw=black!60] 
        (0, -2.0) -- (0, -4.0) node[midway, right=10pt, font=\small\bfseries, text=black] {脱氢 ($-2e^-$)};
\end{scope}

% ==========================================
% 第 3 步: 甲醛 (HCHO)
% ==========================================
\begin{scope}[yshift=-12.4cm]
    \node[atom] at (0,0) {C};
    \node[atom, text=blue!90] at (0, 1.6) {H};
    \node[atom, text=blue!90] at (-1.6,0) {H};
    \node[atom, text=red!80]  at ( 1.6,0) {O};

    \node[c-elec] at (-0.12, 0.8) {}; \node[h-elec] at (0.12, 0.8) {};
    \node[c-elec] at (-0.8, 0.12) {}; \node[h-elec] at (-0.8,-0.12) {};

    \node[c-elec] at (0.65, 0.15) {}; \node[o-elec] at (0.95, 0.15) {};
    \node[c-elec] at (0.65,-0.15) {}; \node[o-elec] at (0.95,-0.15) {};

    \node[o-elec] at ( 1.48, 0.8) {}; \node[o-elec] at ( 1.72, 0.8) {};
    \node[o-elec] at ( 1.48,-0.8) {}; \node[o-elec] at ( 1.72,-0.8) {};

    \draw[dashed, very thick, black!80, rounded corners=12pt] (-1.1, -0.4) rectangle (0.4, 1.1);
    \draw[dashed, very thick, red!80, rounded corners=14pt] (0.5, -1.1) rectangle (2.7, 1.1);

    % 向下箭头 3 (稍微拉长，因为下一个分子很高)
    \draw[-{Stealth[scale=1.2]}, line width=1.5pt, draw=black!60] 
        (0, -1.2) -- (0, -4.5) node[midway, right=10pt, font=\small\bfseries, text=black] {加氧 ($-2e^-$)};
\end{scope}

% ==========================================
% 第 4 步: 甲酸 (HCOOH)
% ==========================================
\begin{scope}[yshift=-20.5cm]
    \node[atom] at (0,0) {C};
    \node[atom, text=blue!90] at (-1.6,0) {H};
    \node[atom, text=red!80]  at ( 1.6,0) {O};
    \node[atom, text=red!80]  at (0, 1.6) {O};
    \node[atom, text=blue!90] at (0, 3.2) {H};

    \node[c-elec] at (-0.8, 0.12) {}; \node[h-elec] at (-0.8,-0.12) {};

    \node[c-elec] at (0.65, 0.15) {}; \node[o-elec] at (0.95, 0.15) {};
    \node[c-elec] at (0.65,-0.15) {}; \node[o-elec] at (0.95,-0.15) {};
    \node[o-elec] at ( 1.48, 0.8) {}; \node[o-elec] at ( 1.72, 0.8) {};
    \node[o-elec] at ( 1.48,-0.8) {}; \node[o-elec] at ( 1.72,-0.8) {};

    \node[c-elec] at (-0.12, 0.8) {}; \node[o-elec] at (0.12, 0.8) {};
    \node[o-elec] at (-0.12, 2.4) {}; \node[h-elec] at (0.12, 2.4) {};
    \node[o-elec] at (-0.8, 1.48) {}; \node[o-elec] at (-0.8, 1.72) {};
    \node[o-elec] at ( 0.8, 1.48) {}; \node[o-elec] at ( 0.8, 1.72) {};

    \draw[dashed, very thick, black!80, rounded corners=10pt] (-1.1, -0.4) rectangle (0.4, 0.4);
    \draw[dashed, very thick, red!80, rounded corners=14pt] (0.5, -1.1) rectangle (2.7, 1.1);  
    \draw[dashed, very thick, red!80, rounded corners=14pt] (-1.1, 0.5) rectangle (1.1, 2.7); 

    % 向下箭头 4
    \draw[-{Stealth[scale=1.2]}, line width=1.5pt, draw=black!60] 
        (0, -1.2) -- (0, -3.5) node[midway, right=10pt, font=\small\bfseries, text=black] {脱氢 ($-2e^-$)};
\end{scope}

% ==========================================
% 第 5 步: 二氧化碳 (CO2)
% ==========================================
\begin{scope}[yshift=-26.0cm]
    \node[atom] at (0,0) {C};
    \node[atom, text=red!80] at (-1.6,0) {O};
    \node[atom, text=red!80] at ( 1.6,0) {O};

    \node[c-elec] at (-0.65, 0.15) {}; \node[o-elec] at (-0.95, 0.15) {};
    \node[c-elec] at (-0.65,-0.15) {}; \node[o-elec] at (-0.95,-0.15) {};
    \node[o-elec] at (-1.48, 0.8) {}; \node[o-elec] at (-1.72, 0.8) {};
    \node[o-elec] at (-1.48,-0.8) {}; \node[o-elec] at (-1.72,-0.8) {};

    \node[c-elec] at (0.65, 0.15) {}; \node[o-elec] at (0.95, 0.15) {};
    \node[c-elec] at (0.65,-0.15) {}; \node[o-elec] at (0.95,-0.15) {};
    \node[o-elec] at ( 1.48, 0.8) {}; \node[o-elec] at ( 1.72, 0.8) {};
    \node[o-elec] at ( 1.48,-0.8) {}; \node[o-elec] at ( 1.72,-0.8) {};

    % 碳的黑框最终退化成极小的中心点
    \draw[dashed, very thick, black!80, rounded corners=8pt] (-0.35, -0.35) rectangle (0.35, 0.35);
    \draw[dashed, very thick, red!80, rounded corners=14pt] (-2.7, -1.1) rectangle (-0.5, 1.1);
    \draw[dashed, very thick, red!80, rounded corners=14pt] (0.5, -1.1) rectangle (2.7, 1.1);
\end{scope}

\end{tikzpicture}
\end{CJK*}
\end{document}
